/**
 * Every API route (`src/app/api/**\/route.ts`) and the guard it runs (DV-03, T20).
 *
 * Data for tests and the live-matrix generator, with each route's permission (Phase 3):
 * nothing reads it at run time. `routeManifest.test.ts` walks the tree and fails, naming the file, on a
 * route that is not listed, an entry without a file, stale methods, or a class its
 * calls no longer give.
 *
 * Kept by hand, maintained with `node scripts/gen-route-manifest.mjs` (from webapp/),
 * which adds new route files, drops gone ones, refreshes methods, re-derives the class
 * of an entry without a `note`, and rewrites `routeManifest.json`, the copy `.mjs`
 * scripts read. A class the calls do not give (an inline role check, a guard the
 * classifier cannot see) carries a `note` saying why, and the generator never changes
 * it. Comments inside the list are not kept: put the reason in `note`.
 */

export const GUARD_CLASSES = [
  /** Sessionless at the middleware (`PUBLIC_PATHS`); the handler may check its own credential. */
  'public',
  /** Plugin call token or runner key (`TOKEN_AUTH_PREFIXES`); never a session. */
  'plugin-token',
  /** The internal service key only (`isInternalRequest`). */
  'internal',
  /** Accepts the scanner key (`isScannerRequest`), with or without the internal key. */
  'scanner',
  /**
   * The caller must see the project (`projectAccess()`: its owner and, with sharing in force, a read
   * share, oversight or break-glass) through `guardProject`, `requireProjectAccess`,
   * `requireProjectOwner`, ..., or `requirePermission` / `withPermission` naming a `projectId` with a
   * permission that acts on a project (can.ts `actsOnProject`: the entry's permission too). Only that
   * permission's level stops a read collaborator, so a write handler asks one at a write level
   * (levelLessHelpers.test.ts).
   */
  'project',
  /** The caller must own the conversation (`requireConversationAccess`, `...BySession`). */
  'conversation',
  /**
   * The user the path names. Reads: that user, the one the session acts as, or the user directory
   * (`users:read`), secrets masked (`requireUserAccess` read). Writes: that user's own session, the internal key, or an admin acting as
   * a passwordless managed account (`requireUserAccess` write, `requireAccountWrite`,
   * `requireOwnBrowserRequest`). Another account's MCP token narrowed or deleted: `users:revoke_sessions`
   * (`requireUserAccess` revoke).
   */
  'user',
  /**
   * An administrator account, by the role getSession reads from the database (`requireAdmin`), or
   * an inline check of the user routes; each then asks its permission through can()
   * (authz/adminPermission.ts).
   */
  'admin-jwt',
  /**
   * Whoever holds platform:plugins, asked of the account read fresh from the database (`requirePluginAdmin`,
   * `lifecyclePost`, `lifecycleGet`): every admin with RBAC_PERMISSIONS_ENABLED off; with it on an admin
   * profile or a member override that holds it.
   */
  'admin-db',
  /** Scoped to the effective user's own rows (`requireEffectiveUser`, `ownerScope`), no project check. */
  'effective-user',
  /**
   * Reads the login session (`getSession`, `requireSession`), no ownership check; with
   * `requirePermission` / `withPermission` and no project, the entry's permission as well. The
   * generator refuses a `projectId` given with a permission that acts on no project (can() ignores
   * it), and `routeManifest.test.ts` one that acts on a project checked with no project, unless
   * its CAPABILITY_ONLY list says why.
   */
  'session',
  /** Only the middleware's JWT check: the handler reads no session at all. */
  'login-only',
  /** A guard none of the above describes (`strictContext`, `handleAction`). */
  'other',
] as const

export type GuardClass = (typeof GUARD_CLASSES)[number]

export type HttpMethod = 'GET' | 'HEAD' | 'POST' | 'PUT' | 'PATCH' | 'DELETE' | 'OPTIONS'

export interface RouteManifestEntry {
  /** URL path with the folder names of dynamic segments: `/api/projects/[id]`. */
  path: string
  guard: GuardClass
  /** The handlers the route file exports, in the order GET HEAD POST PUT PATCH DELETE OPTIONS. */
  methods: HttpMethod[]
  /**
   * The permission each handler asks first (one for every method, or one per method), as
   * routePermissions.test.ts reads it from the handler. `null` for a handler no permission backs:
   * the route's class is a key or none (public, internal, scanner, plugin-token), or it answers
   * every signed-in account (routePermissions.test.ts SESSION_ONLY says why). Absent only where
   * that test's LATER names the step that wires it.
   */
  permission?: string | null | Partial<Record<HttpMethod, string | null>>
  /**
   * The route changes identity, permissions or instance settings, so each write handler accepts
   * only same-origin JSON (`sameOrigin`, then `readJsonBody` when it takes a body; ID-26, T14).
   * `routeManifest.test.ts` reads every flagged file for the calls.
   */
  sameOrigin?: boolean
  /** Why the class is what it is, when the calls alone do not say. */
  note?: string
}

